<?php
declare(strict_types=1);
function annualInputDate($value,string $label):string{$v=trim((string)$value);if(preg_match('#^(\d{2})/(\d{2})/(\d{4})$#',$v,$m))$v=$m[3].'-'.$m[2].'-'.$m[1];return day($v,$label);}
function annualPreview(array $u,array $b):array{$plan=record($u['tenant'],'plans',$b['plan']??'');$cycle=(int)($b['cycle']??0);if(!$plan||$plan['family']!=='geral'||$cycle<2000||$cycle>2200)throw new Fault('Selecione o plano do Quadro Geral e o ano do direito aquisitivo.');$effect=annualInputDate($b['effect']??'','início dos efeitos da progressão');if(substr($effect,0,4)!==(string)($cycle+1))throw new Fault('Para o direito aquisitivo de '.$cycle.', os efeitos devem iniciar em '.($cycle+1).'.');return ['id'=>'preview:'.$plan['id'].':'.$cycle.':'.$effect,'plan'=>$plan['id'],'cycle'=>$cycle,'effect'=>$effect];}
function saveAnnualOrdinance(array $u,array $b):array{$o=annualPreview($u,$b);$published=annualInputDate($b['published']??'','data da publicação da portaria');if($published>today())throw new Fault('A data de publicação está no futuro. Registre a portaria após sua publicação; os efeitos podem iniciar no ano seguinte.');if(substr($published,0,4)!==(string)$o['cycle'])throw new Fault('A publicação deve ocorrer no ano de referência '.$o['cycle'].', até 31/12/'.$o['cycle'].'.');$number=need($b['number']??'','número da portaria',160);foreach(records($u['tenant'],'ordinances') as $existing)if($existing['number']===$number)throw new Fault('Portaria já registrada. Selecione a publicação existente na revisão do lote.',409);$r=save($u['tenant'],'ordinances',['id'=>uid(),'plan'=>$o['plan'],'cycle'=>$o['cycle'],'number'=>$number,'published'=>$published,'effect'=>$o['effect'],'reference'=>need($b['reference']??'','referência da publicação oficial',1000),'created'=>date(DATE_ATOM)]);audit($u['tenant'],'ordinance.register',$r['id']);return $r;}
function finalizeAnnualSelection(array $u,array $b):array{$preview=annualPreview($u,$b);$rank=rankAnnual($u,$preview['plan'],$preview['cycle'],$b['criteria']??[]);$ids=$b['eligibilityIds']??[];validateSelection($rank,$ids);$budget=annualBudget($u,$ids,$preview,$b['budgetOptions']??[]);if(!$budget['complete'])throw new Fault('Complete os vínculos salariais antes de registrar a portaria.');if(!hash_equals($budget['token'],(string)($b['budgetToken']??'')))throw new Fault('A seleção, a data de efeito ou os valores mudaram. Recalcule o impacto antes de confirmar.',409);if(($b['confirmed']??false)!==true)throw new Fault('Confirme a revisão da seleção e da publicação.');
 if(!empty($b['ordinanceId'])){$o=record($u['tenant'],'ordinances',$b['ordinanceId']);if(!$o||$o['plan']!==$preview['plan']||$o['cycle']!==$preview['cycle']||$o['effect']!==$preview['effect'])throw new Fault('A portaria selecionada deve corresponder ao plano, ano e data de efeito da seleção.');}else $o=saveAnnualOrdinance($u,$b);
 $actualBudget=annualBudget($u,$ids,$o,$b['budgetOptions']??[]);$result=annualApi($u,'grant','POST',array_replace($b,['ordinanceId'=>$o['id'],'budgetToken'=>$actualBudget['token']]));return $result+['ordinanceId'=>$o['id']];}
